AA.add('plan', [
  /* Safety */
  { id: "pl_crisis", group: "Safety", t: "Crisis and safety plan agreed: warning signs, coping steps, people to contact and crisis numbers, with the GP informed.", src: "Clinical practice; NICE NG225 (risk scales not used to predict suicide)" },
  { id: "pl_safeguarding", group: "Safety", t: "Safeguarding or domestic abuse concerns referred under local procedures, and the outcome recorded.", src: "Clinical practice; RCPsych CR235 11.6" },
  { id: "pl_drivesafe", bands: ["y17", "adult"], group: "Safety", t: "Advised not to drive while unsafe (for example sleepy, intoxicated or seriously distracted) until reviewed, and the advice recorded.", src: "Clinical practice; GOV.UK ADHD and driving" },

  /* After diagnosis */
  { id: "pl_psychoed", group: "After diagnosis", t: "Diagnosis explained in plain language, with time to reflect and ask questions. Structured discussion held on how ADHD could affect life: positives and negatives of the diagnosis, impulsive behaviour, relationships, coexisting conditions, and the risk of substance misuse and self-medication.", src: "NICE NG87 1.4.3; UKAAN AQAS 2024 Table 2" },
  { id: "pl_written", group: "After diagnosis", t: "Written information about ADHD given, suited to the person's needs, with details of support groups, reliable websites, and education and employment support.", src: "NICE NG87 1.4.4, 1.4.5" },
  { id: "pl_family", ages: "adult", group: "After diagnosis", t: "With consent, advice offered to family members or carers about ADHD, relationships and the importance of structure in daily activities.", src: "NICE NG87 1.4.10" },
  { id: "pl_environment", ages: "adult", group: "After diagnosis", t: "Environmental modifications agreed for home and work or study (for example fewer distractions, written instructions, shorter periods of focus with movement breaks, reminders and routines), with a date to review them.", src: "NICE NG87 1.5.15 and glossary (environmental modifications)" },
  { id: "pl_adjustments", group: "After diagnosis", t: "Reasonable adjustments at work or in education discussed, including the duty on employers and education providers to make them (Equality Act 2010; Disability Discrimination Act 1995 in Northern Ireland).", src: "NICE NG87 1.4.3; Equality Act 2010" },
  { id: "pl_accesstowork", ages: "adult", group: "After diagnosis", t: "Access to Work explained: government support for practical help at work, such as coaching or equipment (England, Scotland and Wales; Northern Ireland has its own scheme).", src: "GOV.UK Access to Work" },
  { id: "pl_letter", ages: "adult", group: "After diagnosis", t: "With consent, a letter provided for the employer, occupational health, college or university, describing the diagnosis, its effects and suggested adjustments; students told about Disabled Students' Allowance and the disability service.", src: "NICE NG87 1.4.3, 1.4.12; CADDRA 4.1 (accommodation letters); Clinical practice" },
  { id: "pl_options", ages: "adult", group: "After diagnosis", t: "Treatment options explained: environmental changes first; medicine (lisdexamfetamine or methylphenidate first line for adults) if symptoms still cause significant impairment in at least one domain after these changes are made and reviewed; and, as a minimum when non-drug treatment is indicated, a structured supportive psychological intervention focused on ADHD with regular follow-up, which may include CBT. Non-drug treatment is considered for people who choose not to take medicine, find it hard to take regularly, or find it ineffective or intolerable, and alongside medicine when significant impairment remains.", src: "NICE NG87 1.5.15, 1.5.16, 1.5.17, 1.5.18, 1.7.11" },
  { id: "pl_shared", group: "After diagnosis", t: "Shared decision on treatment: benefits and harms of drug and non-drug options, the benefits of a healthy lifestyle including exercise, how coexisting conditions affect the choices, and what may get in the way of taking treatment regularly; preferences, concerns, measurable goals and baseline symptom and impairment ratings recorded; decisions can be revisited at any time.", src: "NICE NG87 1.5.4, 1.5.6, 1.7.26, 1.9.2; UKAAN AQAS 2024 Table 2" },
  { id: "pl_dvla", bands: ["y17", "adult"], group: "After diagnosis", t: "Driving discussed: the person must tell the DVLA (DVA in Northern Ireland) only if ADHD or its medicine affects their ability to drive safely.", src: "NICE NG87 1.4.3; GOV.UK ADHD and driving" },
  { id: "pl_gp", group: "After diagnosis", t: "Report sent to the GP and, with consent, to clinicians treating coexisting conditions; shared care to be agreed with the GP if medicine is started.", src: "NICE NG87 1.1.2, 1.4.13; UKAAN AQAS 2024 Table 2" },

  /* Before any medication */
  { id: "pl_recheck", group: "Before any medication", t: "Confirmed that the person still meets the criteria for ADHD and needs treatment; coexisting conditions, work or education circumstances and care needs reviewed.", src: "NICE NG87 1.7.4" },
  { id: "pl_cardiohx", group: "Before any medication", t: "Cardiovascular history taken: congenital heart disease or heart surgery, breathlessness or fainting on exertion, fainting with fright or noise, sudden-onset regular palpitations, chest pain, and sudden cardiac death in a first-degree relative under 40.", src: "NICE NG87 1.7.4, 1.7.5" },
  { id: "pl_obs", ages: "adult", group: "Before any medication", t: "Baseline pulse and blood pressure (with an appropriately sized cuff), height and weight measured and recorded.", src: "NICE NG87 1.7.4" },
  { id: "pl_ecg", group: "Before any medication", t: "ECG only if one of the heart-history features in the cardiovascular history is present or a coexisting condition is treated with a medicine that may increase cardiac risk; cardiology opinion sought before medicine if any of those features applies, including blood pressure in the hypertensive range.", src: "NICE NG87 1.7.4, 1.7.5" },
  { id: "pl_misuse", group: "Before any medication", t: "Risk of substance misuse and diversion assessed and recorded, and the preparation and supply arrangements chosen to reduce it.", src: "NICE NG87 1.7.4, 1.7.23, 1.7.24" },
  { id: "pl_medreview", group: "Before any medication", t: "Medical and mental health history and current medicines reviewed for contraindications, cautions and interactions in the product information: for example MAOI use in the last 14 days, glaucoma, hyperthyroidism, phaeochromocytoma, severe or uncontrolled hypertension, structural heart or cerebrovascular disease, and (for methylphenidate) severe depression, suicidal tendencies, psychotic symptoms, mania, anorexia nervosa or borderline personality disorder. Pregnancy and breastfeeding discussed before prescribing.", src: "NICE NG87 1.7.4; product information (SmPC section 4.3)" },
  { id: "pl_prescriber", group: "Before any medication", t: "Medicine to be started only by a healthcare professional with training and expertise in diagnosing and managing ADHD, with dose adjustment and review by an ADHD specialist.", src: "NICE NG87 1.7.2; NICE QS39 statement 6" },

  /* Other needs */
  { id: "pl_treatfirst", group: "Other needs", t: "A coexisting condition that takes priority (for example psychosis, bipolar disorder, severe depression or severe anxiety) to be treated or stabilised first, with ADHD treatment planned afterwards. Substance misuse to be stabilised, but it can be treated at the same time as ADHD; milder mood or anxiety problems can be treated alongside ADHD.", src: "Kooij et al. 2019 section 7.2; CADDRA 4.1; RCPsych CR235 section 10" },
  { id: "pl_refer", group: "Other needs", t: "Referral or signposting for coexisting conditions found (for example talking therapies, an autism assessment, a sleep service, an eating disorder service or an addiction service).", src: "NICE NG87 1.3.4; Clinical practice" },
  { id: "pl_tests", group: "Other needs", t: "Blood tests or other investigations only where the history suggests a medical cause (for example thyroid function, full blood count and ferritin, or a sleep study).", src: "AADPA 2022 (tests only if clinically indicated); NICE NG145" },
  { id: "pl_neuropsych", group: "Other needs", t: "Neuropsychological or educational psychology assessment if a learning disorder or intellectual disability is suspected, or if impairment is far greater than the symptoms explain.", src: "BAP 2014; RCPsych CR235 9.6" },

  /* If ADHD not diagnosed */
  { id: "pl_nodx_explain", group: "If ADHD not diagnosed", t: "Outcome explained: which criteria were not met, or what better explains the difficulties, with the reasoning set out in the report.", src: "UKAAN AQAS 2024 (report contents); Clinical practice" },
  { id: "pl_nodx_info", group: "If ADHD not diagnosed", t: "Information and support still offered, including practical strategies for the difficulties described.", src: "NICE NG87 1.4.4" },
  { id: "pl_nodx_signpost", group: "If ADHD not diagnosed", t: "Signposted or referred for what better explains the difficulties (for example mood, anxiety, trauma, sleep or addiction services, or the GP for medical tests).", src: "NICE NG87 1.4.4; Clinical practice" },
  { id: "pl_nodx_subthreshold", group: "If ADHD not diagnosed", t: "If subthreshold, this is stated, with needs-led support and adjustments that do not depend on a diagnosis.", src: "UKAAN AQAS 2024; DHSC independent review 2026 (needs-led plus diagnosis)" },
  { id: "pl_nodx_reassess", group: "If ADHD not diagnosed", t: "Criteria for re-assessment agreed: for example new informant or school evidence, symptoms that persist once a coexisting condition is treated, or a change in circumstances; if the decision is deferred, the missing evidence is named with a review date.", src: "Clinical practice" },

  /* Children and young people (ages 6-17) */
  { id: "pl_young_options", ages: "young", group: "After diagnosis", t: "Treatment options explained to the child or young person and their family: information and ADHD-focused support for parents and carers, and changes at home and school, come first; medicine only if significant impairment persists after those changes have been made and reviewed. If medicine is needed, the NICE order for ages 6 to 17 is: methylphenidate first; lisdexamfetamine after an adequate 6-week methylphenidate trial without enough benefit; dexamfetamine if lisdexamfetamine helps but its longer effect cannot be tolerated; atomoxetine or guanfacine if methylphenidate or lisdexamfetamine cannot be tolerated, or neither helped after separate 6-week trials at adequate doses.", src: "NICE NG87 1.5.10, 1.5.13, 1.7.7, 1.7.8, 1.7.9, 1.7.10" },
  { id: "pl_young_sharing", ages: "young", group: "After diagnosis", t: "Agreed who will receive the report and plan (GP, school, social worker) and on whose consent: the young person's own if they are Gillick competent (under 16) or aged 16 or 17 with capacity, otherwise a person with parental responsibility. A parent's consent cannot replace a competent young person's. Information is shared without consent only when required by law or a court, when it is needed to protect the child or young person or someone else from serious harm (the public interest), or, for a child who cannot decide, when it is in their best interests; the reason is recorded.", src: "GMC 0-18 years: principles of confidentiality (sharing information with consent, and paragraphs 46-52 on sharing without consent); local safeguarding procedures" },
  { id: "pl_young_info", ages: "young", group: "Support for parents and carers", t: "Information about ADHD given to the child or young person and their parents or carers, and ADHD-focused support offered to parents and carers. It can be group-based and as short as 1 or 2 sessions, covers the causes and impact of ADHD and parenting strategies, includes liaison with school (with consent), and involves both parents or carers where feasible.", src: "NICE NG87 1.5.10" },
  { id: "pl_young_parenttraining", ages: "young", group: "Support for parents and carers", t: "Oppositional or conduct symptoms: a parent-training programme offered to parents and carers as well as group ADHD-focused support; individual parent training considered if the family has particular difficulty attending a group, or its needs are too complex for one.", src: "NICE NG87 1.5.11, 1.5.12; NICE CG158" },
  { id: "pl_young_school", ages: "young", group: "School and education", t: "With consent, the school or college contacted to explain that the diagnosis is valid and how ADHD is likely to affect school life; that any coexisting conditions are distinct and may need different adjustments; the treatment plan and special educational needs, including reasonable adjustments and environmental modifications; and the value of feedback from school. Repeated when symptoms change and at each move of school, or to college or university.", src: "NICE NG87 1.4.12" },
  { id: "pl_young_letter", ages: "young", group: "School and education", t: "With consent, a written summary sent to the school or college (for example to the SENCO): the diagnosis, how ADHD shows for this child in class, suggested adjustments (such as seating away from distractions, short tasks with movement breaks, instructions given one at a time and in writing), and a named contact for feedback on progress and treatment.", src: "NICE NG87 1.4.12; Clinical practice" },
  { id: "pl_young_sen", ages: "young", group: "School and education", t: "Special educational needs discussed with the family and the school: what SEN support is in place and whether it works, and whether to ask the local authority for an education, health and care (EHC) needs assessment if needs are not being met. This applies in England; Wales, Scotland and Northern Ireland have their own systems.", src: "Clinical practice" },
  { id: "pl_young_diet", ages: "young", group: "Support for parents and carers", t: "Diet discussed with the family: a balanced diet, good nutrition and regular exercise encouraged; artificial colourings and additives not removed as a general treatment; no fatty acid (for example omega-3) supplements for ADHD; if a food or drink seems to affect behaviour, a food and behaviour diary, with referral to a dietitian if the diary supports a link; families told there is no evidence on the long-term benefits or harms of a few-foods diet.", src: "NICE NG87 1.6.1, 1.6.2, 1.6.3, 1.6.4, 1.6.5" },
  { id: "pl_young_cbt", ages: "young", group: "After diagnosis", t: "If medicine has helped but significant impairment remains, CBT considered for the young person, covering social skills with peers, problem-solving, self-control, active listening, and dealing with and expressing feelings.", src: "NICE NG87 1.5.14" },
  { id: "pl_young_transition", ages: "young", bands: ["teen", "y17"], group: "After diagnosis", t: "Transition planned for a young person likely to need ADHD care as an adult: planning starts by Year 9 (age 13 to 14) at the latest; a named worker coordinates it; the need for treatment is reassessed at school-leaving age; a formal meeting between children's and adult services is considered, with full information for the young person; the care programme approach is used from 16 where appropriate; and transfer is usually complete by 18, involving the young person and, where appropriate, the parent or carer.", src: "NICE NG87 1.1.4, 1.1.5; NICE NG43 1.2.1, 1.2.5" },
  { id: "pl_young_lac", ages: "young", group: "After diagnosis", t: "Looked-after child: with the right consent, the social worker, carers and the virtual school (England) or local equivalent told about the diagnosis and plan, and who can consent to treatment confirmed.", src: "Clinical practice" },
  { id: "pl_young_medcriteria", ages: "young", group: "Before any medication", t: "Medicine offered only when all of these hold: ADHD symptoms still cause persistent significant impairment in at least one domain after environmental modifications have been put in place and reviewed; the child or young person and their parents or carers have discussed information about ADHD; and a baseline assessment has been done.", src: "NICE NG87 1.5.13, 1.5.4, 1.7.4" },
  { id: "pl_young_baseline", ages: "young", group: "Before any medication", t: "Baseline before any medicine: height and weight plotted on a growth chart; pulse and blood pressure (with an appropriately sized cuff) compared with the normal range for age, and the chart used recorded. If blood pressure is consistently above the 95th centile for age and height, refer to a paediatric hypertension specialist before starting.", src: "NICE NG87 1.7.4, 1.7.6; Clinical practice (record the chart used)" },
  { id: "pl_young_nodx_school", ages: "young", group: "If ADHD not diagnosed", t: "With consent, the outcome shared with the school, with strategies for the difficulties seen and support for the family that does not depend on a diagnosis, including a parent-training programme if there are conduct problems.", src: "Clinical practice; NICE CG158" },
  { id: "pl_young_family", ages: "young", group: "Support for parents and carers", t: "Advice given to parents and carers about the importance of positive contact between parent or carer and child, clear and appropriate rules about behaviour with consistent handling, and structure in the child's or young person's day. Explained that any advice to attend parent training does not mean bad parenting: it builds the extra parenting skills that children with ADHD need.", src: "NICE NG87 1.4.9, 1.4.11" },
  { id: "pl_young_environment", ages: "young", group: "After diagnosis", t: "Environmental modifications agreed at home and, with the school, in class (for example fewer distractions, short tasks with movement breaks, instructions given one at a time and in writing, routines, and support from a teaching assistant where appropriate), with a review date, before any medicine is considered.", src: "NICE NG87 1.5.13, 1.4.12 and glossary (environmental modifications)" }
]);
